UPDATE public.checkout_inventory i
SET product_data = (i.product_data - 'images') || '{"image":""}'::jsonb
FROM targets t JOIN assets a USING(slug)
WHERE i.sku = t.sku AND i.product_data->>'slug' = t.slug
  AND i.product_data->>'image' = a.url AND i.product_data->'images' = a.images
RETURNING i.sku;
